1: import React, { createContext, useContext, useEffect, useState } from "react";
2: 
3: type Theme = "dark" | "light" | "system";
4: 
5: interface ThemeProviderProps {
6:   children: React.ReactNode;
7:   defaultTheme?: Theme;
8:   storageKey?: string;
9: }
10: 
11: interface ThemeProviderState {
12:   theme: Theme;
13:   setTheme: (theme: Theme) => void;
14: }
15: 
16: const ThemeProviderContext = createContext<ThemeProviderState | undefined>(
17:   undefined
18: );
19: 
20: export function ThemeProvider({
21:   children,
22:   defaultTheme = "system",
23:   storageKey = "vite-ui-theme",
24:   ...props
25: }: ThemeProviderProps) {
26:   const [theme, setTheme] = useState<Theme>(
27:     () => (localStorage.getItem(storageKey) as Theme) || defaultTheme
28:   );
29: 
30:   useEffect(() => {
31:     const root = window.document.documentElement;
32: 
33:     root.classList.remove("light", "dark");
34: 
35:     if (theme === "system") {
36:       const systemTheme = window.matchMedia("(prefers-color-scheme: dark)")
37:         .matches
38:         ? "dark"
39:         : "light";
40:       root.classList.add(systemTheme);
41:       return;
42:     }
43: 
44:     root.classList.add(theme);
45:   }, [theme]);
46: 
47:   const value = {
48:     theme,
49:     setTheme: (theme: Theme) => {
50:       localStorage.setItem(storageKey, theme);
51:       setTheme(theme);
52:     },
53:   };
54: 
55:   return (
56:     <ThemeProviderContext.Provider {...props} value={value}>
57:       {children}
58:     </ThemeProviderContext.Provider>
59:   );
60: }
61: 
62: export const useTheme = () => {
63:   const context = useContext(ThemeProviderContext);
64: 
65:   if (context === undefined)
66:     throw new Error("useTheme must be used within a ThemeProvider");
67: 
68:   return context;
69: };

